// Source template for the built service worker (public/sw.js, generated by
// scripts/build-service-worker.mjs). Do not edit sw.js directly — it's regenerated
// on every build and gitignored.
importScripts("https://storage.googleapis.com/workbox-cdn/releases/7.1.0/workbox-sw.js");

if (workbox) {
  self.skipWaiting();
  workbox.core.clientsClaim();

  // Precaches the static PWA assets listed in workbox-config.js. Real runtime
  // caching strategies for pages and API data land in Phase 9.
  workbox.precaching.precacheAndRoute(self.__WB_MANIFEST);
} else {
  console.error("[sw] Workbox failed to load from CDN");
}
